 void OpenCityView(){if(City==null)return;if(!cityDataOnly){cityActive=true;SetPause(true);DigitalKingdomTransit.Character=Character;DigitalKingdomTransit.Levels=Levels;DigitalKingdomTransit.Inventory=inventorySettings;DigitalKingdomTransit.Enter(CaptureDungeonSave(),ActiveMap,City.scenePath);return;}foreach(var l in City.locations)if(l!=null&&l.initiallyUnlocked&&!cityProgress.unlockedLocations.Contains(l.id))cityProgress.unlockedLocations.Add(l.id);if(!cityActive){cityCameraMask=view.cullingMask;cityCameraClearFlags=view.clearFlags;cityCameraBackground=view.backgroundColor;}cityActive=true;citySelection=cityServiceSelection=0;cityTransition=Time.unscaledTime;ClearMovementInput();ResetConversationCamera();SetPause(true);AudioListener.pause=false;view.cullingMask=0;view.clearFlags=CameraClearFlags.SolidColor;view.backgroundColor=Color.black;DungeonAudio.SetCombat(false);}
 void CloseCityView(){if(!cityActive)return;cityActive=false;if(view!=null){view.cullingMask=cityCameraMask;view.clearFlags=cityCameraClearFlags;view.backgroundColor=cityCameraBackground;}SetPause(false);}
 public bool ExitDigitalKingdom(){if(!cityActive||worldDialogue.Active)return false;if(cityDataOnly){if(!Open(cityProgress.returnCell)){if(!Open(City.fallbackReturnCell))return false;cityProgress.returnCell=City.fallbackReturnCell;cityProgress.returnHeading=City.fallbackReturnHeading;}cityProgress.inCity=false;cityProgress.locationId="";DigitalKingdomTransit.Return(CaptureCityModelSave(),ActiveMap,City.fallbackDungeonScene);return true;}var destination=cityProgress.returnCell;if(!Open(destination)){destination=City.fallbackReturnCell;if(!Open(destination)){message="No existe una entrada de retorno válida.";return false;}}cityProgress.inCity=false;cityProgress.locationId="";CloseCityView();WarpPlayer(destination,cityProgress.returnHeading);return true;}
 public bool OpenCityLocation(string id){if(!cityActive||worldDialogue.Active)return false;var l=Array.Find(City.locations,x=>x!=null&&x.id==id);if(l==null||!l.available||!cityProgress.unlockedLocations.Contains(id))return false;if(l.service==DigitalKingdomService.Exit)return ExitDigitalKingdom();cityProgress.locationId=id;cityServiceSelection=0;cityTransition=Time.unscaledTime;DungeonAudio.Play(DungeonAudio.Cue.Confirm);if(l.dialogue.Length>0&&(!l.uniqueConversation||!cityProgress.conversationsSeen.Contains(id)))worldDialogue.Begin(l.dialogue,()=>{if(!cityProgress.conversationsSeen.Contains(id))cityProgress.conversationsSeen.Add(id);});return true;}
