 void RestoreCityProgress(DigitalKingdomProgress value){CloseCityView();cityProgress=value??new DigitalKingdomProgress();if(cityProgress.unlockedLocations==null)cityProgress.unlockedLocations=new List<string>();if(cityProgress.conversationsSeen==null)cityProgress.conversationsSeen=new List<string>();if(cityProgress.inCity)OpenCityView();}
 List<TransferNodeDefinition> CityTravelNodes(){var result=new List<TransferNodeDefinition>();foreach(string id in refuge.unlockedNodes){var node=FindTransferNode(id);if(node!=null&&Open(node.cell))result.Add(node);}return result;}
 bool CityTravel(string id){if(!cityActive||!refuge.unlockedNodes.Contains(id)||FindTransferNode(id)==null)return false;if(cityDataOnly){var node=FindTransferNode(id);var data=CaptureCityModelSave();data.cell=node.cell;data.heading=node.arrivalHeading;data.city.inCity=false;data.city.locationId="";DigitalKingdomTransit.Travel(data,ActiveMap,City.fallbackDungeonScene,id);return true;}CloseCityView();cityProgress.inCity=false;cityProgress.locationId="";return TravelToNode(id);}
 string[] CityServices(){var l=CityLocation;if(l==null)return new string[0];switch(l.service){case DigitalKingdomService.Temple:return new[]{"Restore & Register Continue","Save Game","Return to City"};case DigitalKingdomService.Travel:var nodes=CityTravelNodes();var labels=new List<string>();foreach(var n in nodes)labels.Add(n.displayName);labels.Add("Return to City");return labels.ToArray();case DigitalKingdomService.Shop:return new[]{"View Items","Return to City"};case DigitalKingdomService.Research:return new[]{"HACK upgrades — In development","Special attacks — In development","Minigame upgrades — In development","Digital anomalies — In development","Return to City"};default:return new[]{"Service — In development","Return to City"};}}
 void ExecuteCityService(int index){var labels=CityServices();if(index<0||index>=labels.Length)return;if(index==labels.Length-1){LeaveCityLocation();return;}var l=CityLocation;switch(l.service){case DigitalKingdomService.Temple:RegisterCityTemple();if(index==1)OpenSaveSlots(false);else worldDialogue.Begin(new[]{new WorldDialogueLine("PRIEST","Integrity restored. Continue registered.")});break;case DigitalKingdomService.Travel:CityTravel(CityTravelNodes()[index].id);break;case DigitalKingdomService.Shop:var text=new List<WorldDialogueLine>();foreach(string id in l.stockIds){var item=Array.Find(inventorySettings.items,i=>i.id==id);if(item!=null)text.Add(new WorldDialogueLine("SHOPKEEPER",item.displayName+" — In your inventory: "+itemCounts[Array.IndexOf(inventorySettings.items,item)]+". Purchases are in development."));}if(text.Count==0)text.Add(new WorldDialogueLine("SHOPKEEPER","The stock is being prepared."));worldDialogue.Begin(text.ToArray());break;default:worldDialogue.Begin(new[]{new WorldDialogueLine(l.npcName,"This service is in development.")});break;}}
 bool UpdateCityInput(){if(!cityActive)return false;if(saveSlotsOpen){UpdateSaveSlotInput();return true;}var k=Keyboard.current;var pad=Gamepad.current;bool confirm=(k!=null&&(k.enterKey.wasPressedThisFrame||k.eKey.wasPressedThisFrame||k.spaceKey.wasPressedThisFrame))||(pad!=null&&pad.buttonSouth.wasPressedThisFrame);
  if(worldDialogue.Active){if(confirm)worldDialogue.Advance(Layout.lettersPerSecond);return true;}
  bool back=(k!=null&&k.escapeKey.wasPressedThisFrame)||(pad!=null&&pad.buttonEast.wasPressedThisFrame);if(back&&CityLocation!=null){LeaveCityLocation();return true;}if(k!=null&&k.f5Key.wasPressedThisFrame){OpenSaveSlots(false);return true;}
  int delta=(k!=null&&k.downArrowKey.wasPressedThisFrame)||(pad!=null&&pad.dpad.down.wasPressedThisFrame)?1:(k!=null&&k.upArrowKey.wasPressedThisFrame)||(pad!=null&&pad.dpad.up.wasPressedThisFrame)?-1:0;
  if(CityLocation==null){int count=City.locations.Length;if(count==0)return true;if(delta!=0){citySelection=(citySelection+delta+count)%count;DungeonAudio.Play(DungeonAudio.Cue.TextAdvance);}if(confirm)OpenCityLocation(City.locations[citySelection].id);}else{int count=CityServices().Length;if(delta!=0){cityServiceSelection=(cityServiceSelection+delta+count)%count;DungeonAudio.Play(DungeonAudio.Cue.TextAdvance);}if(confirm)ExecuteCityService(cityServiceSelection);}return true;
 }
